#!/usr/bin/env python3
"""
apply_features.py - installs the "group 1" feature changes directly into this repo.

Why this file exists: applying a .patch on Windows can fail when the downloaded
patch gets CRLF line endings or a different encoding ("corrupt patch"). This
script embeds every changed file as base64 (pure ASCII, encoding-safe) and
writes the files with UTF-8 and LF line endings - immune to those problems.

Usage (from the repo root, e.g. C:/Project/py_ai/py_ai_project):
    python apply_features.py
    git add -A
    git commit -m "feat: add group-1 features (quiet, verbose, no-tree, no-token-count)"
    python -m pytest -q
"""

