def main() -> int:
    written = 0
    for rel, b64 in FILES.items():
        target = ROOT / rel
        try:
            data = base64.b64decode(b64)
        except Exception as exc:  # pragma: no cover
            print(f"ERROR: corrupt base64 for {rel}: {exc}", file=sys.stderr)
            return 1
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)  # UTF-8 + LF, exactly as committed
        written += 1
        print(f"  wrote {rel} ({len(data)} bytes)")
    print(f"\nDone: {written} files written.")
    print("Next steps:")
    print("  git add -A")
    print('  git commit -m "feat: add group-1 features (quiet, verbose, no-tree, no-token-count)"')
    print("  python -m pytest -q")
    return 0

if __name__ == "__main__":
    sys.exit(main())
